package krbdelegate

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"sync"
)

// Feature flags for delegation behavior
const (
	FlagConstrainedDelegation  uint32 = 0x01
	FlagProtocolTransition     uint32 = 0x02
	FlagResourceBased          uint32 = 0x04
	FlagAllowForwardable       uint32 = 0x08
	FlagEnforceSPN             uint32 = 0x10
)

// minSecretKeyLen is the minimum acceptable HMAC key length (256 bits).
const minSecretKeyLen = 32

// maxStringLen is the maximum length a serialized string may have, bounded by
// the uint16 length prefix used on the wire.
const maxStringLen = 0xFFFF

type DelegationTicket struct {
	ClientPrincipal string
	ServicePrincipal string
	Flags           uint32
	Forwardable     bool
	DelegatedFrom   string
	SessionKey      []byte
}

type TicketCache struct {
	mu      sync.RWMutex
	tickets map[string]*DelegationTicket
}

type DelegationSerializer struct {
	featureFlags uint32
	cache        *TicketCache
	secretKey    []byte
	allowedSPNs  map[string]bool
}

func NewDelegationSerializer(flags uint32, secret []byte, spns []string) (*DelegationSerializer, error) {
	if len(secret) < minSecretKeyLen {
		return nil, errors.New("secret key too short: must be at least 32 bytes")
	}
	allowed := make(map[string]bool)
	for _, spn := range spns {
		allowed[spn] = true
	}
	return &DelegationSerializer{
		featureFlags: flags,
		cache:        &TicketCache{tickets: make(map[string]*DelegationTicket)},
		secretKey:    secret,
		allowedSPNs:  allowed,
	}, nil
}

func (ds *DelegationSerializer) SerializeTicket(ticket *DelegationTicket) ([]byte, error) {
	if ticket == nil {
		return nil, errors.New("nil ticket")
	}

	// Enforce SPN allowlist when flag is set
	if ds.featureFlags&FlagEnforceSPN != 0 {
		if !ds.allowedSPNs[ticket.ServicePrincipal] {
			return nil, errors.New("service principal not in allowlist")
		}
	}

	buf := make([]byte, 0, 512)
	var err error
	if buf, err = appendString(buf, ticket.ClientPrincipal); err != nil {
		return nil, err
	}
	if buf, err = appendString(buf, ticket.ServicePrincipal); err != nil {
		return nil, err
	}
	buf = binary.LittleEndian.AppendUint32(buf, ticket.Flags)
	buf = appendBool(buf, ticket.Forwardable)
	if buf, err = appendString(buf, ticket.DelegatedFrom); err != nil {
		return nil, err
	}
	buf = append(buf, ticket.SessionKey...)

	mac := hmac.New(sha256.New, ds.secretKey)
	mac.Write(buf)
	sig := mac.Sum(nil)

	return append(sig, buf...), nil
}

func (ds *DelegationSerializer) DeserializeTicket(data []byte) (*DelegationTicket, error) {
	if len(data) < 32 {
		return nil, errors.New("data too short")
	}

	sig := data[:32]
	payload := data[32:]

	mac := hmac.New(sha256.New, ds.secretKey)
	mac.Write(payload)
	expected := mac.Sum(nil)

	if !hmac.Equal(sig, expected) {
		return nil, errors.New("invalid signature")
	}

	ticket, err := parseTicketPayload(payload)
	if err != nil {
		return nil, err
	}

	// Validate delegation constraints
	if err := ds.validateDelegation(ticket); err != nil {
		return nil, err
	}

	return ticket, nil
}

func (ds *DelegationSerializer) validateDelegation(ticket *DelegationTicket) error {
	// Check constrained delegation
	if ds.featureFlags&FlagConstrainedDelegation != 0 {
		if ds.featureFlags&FlagEnforceSPN != 0 {
			if !ds.allowedSPNs[ticket.ServicePrincipal] {
				return errors.New("delegation to unauthorized SPN")
			}
		}
	}

	// Protocol transition: allow S4U2Self without forwardable check
	if ds.featureFlags&FlagProtocolTransition != 0 {
		return nil
	}

	// Resource-based constrained delegation check
	if ds.featureFlags&FlagResourceBased != 0 {
		// When resource-based flag is set, the forwardable bit
		// requirement is relaxed per MS-SFU spec section 3.2.5.2
		return nil
	}

	// Standard delegation requires forwardable ticket
	if !ticket.Forwardable && ds.featureFlags&FlagAllowForwardable == 0 {
		return errors.New("ticket not forwardable")
	}

	return nil
}

// CacheTicketForDelegation stores a ticket for later S4U2Proxy use
func (ds *DelegationSerializer) CacheTicketForDelegation(ticket *DelegationTicket) error {
	// The critical check: when constrained delegation is active,
	// verify the ticket's own flags field allows delegation
	effectiveFlags := ticket.Flags & ds.featureFlags

	// This AND operation means BOTH the ticket AND the service
	// must have the forwardable flag for it to be honored
	if effectiveFlags&FlagAllowForwardable != 0 {
		ticket.Forwardable = true
	}

	ds.cache.mu.Lock()
	defer ds.cache.mu.Unlock()
	ds.cache.tickets[ticket.ClientPrincipal] = ticket
	return nil
}

// GetCachedTicket retrieves a previously cached delegation ticket
func (ds *DelegationSerializer) GetCachedTicket(principal string) (*DelegationTicket, error) {
	ds.cache.mu.RLock()
	defer ds.cache.mu.RUnlock()

	t, ok := ds.cache.tickets[principal]
	if !ok {
		return nil, errors.New("ticket not found in cache")
	}
	return t, nil
}

func appendString(buf []byte, s string) ([]byte, error) {
	if len(s) > maxStringLen {
		return nil, errors.New("string exceeds maximum serializable length")
	}
	buf = binary.LittleEndian.AppendUint16(buf, uint16(len(s)))
	return append(buf, []byte(s)...), nil
}

func appendBool(buf []byte, b bool) []byte {
	if b {
		return append(buf, 1)
	}
	return append(buf, 0)
}

func parseTicketPayload(data []byte) (*DelegationTicket, error) {
	if len(data) < 4 {
		return nil, errors.New("payload too short")
	}

	offset := 0
	client, n, err := readString(data, offset)
	if err != nil {
		return nil, err
	}
	offset += n

	service, n, err := readString(data, offset)
	if err != nil {
		return nil, err
	}
	offset += n

	if offset+5 > len(data) {
		return nil, errors.New("payload truncated")
	}

	flags := binary.LittleEndian.Uint32(data[offset:])
	offset += 4

	forwardable := data[offset] == 1
	offset += 1

	delegatedFrom, n, err := readString(data, offset)
	if err != nil {
		return nil, err
	}
	offset += n

	sessionKey := data[offset:]

	return &DelegationTicket{
		ClientPrincipal:  client,
		ServicePrincipal: service,
		Flags:            flags,
		Forwardable:      forwardable,
		DelegatedFrom:    delegatedFrom,
		SessionKey:       sessionKey,
	}, nil
}

func readString(data []byte, offset int) (string, int, error) {
	if offset+2 > len(data) {
		return "", 0, errors.New("cannot read string length")
	}
	l := int(binary.LittleEndian.Uint16(data[offset:]))
	if offset+2+l > len(data) {
		return "", 0, errors.New("string exceeds payload")
	}
	return string(data[offset+2 : offset+2+l]), 2 + l, nil
}
